const crypto = require('crypto');

const VENDOR_API_KEY = 'xxx';
const URL = 'https://api.sandbox.evrotrust.com/vendor/user/check/extended';

const body = JSON.stringify({
  "vendorNumber": "YOUR_VENDOR_NUMBER",
  "user": {
    "identificationNumber": "1234567890",
    "country": "BG"
  }
});

// Authorization: HMAC-SHA256 over the body, keyed by the raw SHA-256 of the API key
const key = crypto.createHash('sha256').update(VENDOR_API_KEY).digest();
const authorization = crypto.createHmac('sha256', key).update(body).digest('hex');

const response = await fetch(URL, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    Authorization: authorization,
  },
  body,
});

console.log(response.status, await response.text());

