const crypto = require('crypto');
const fs = require('fs');

const VENDOR_API_KEY = 'xxx';
const URL = 'https://api.sandbox.evrotrust.com/vendor/document/group/online';

// The HMAC covers this exact string, so sign the same value that is sent.
// Append one `document` part per entry in data.documents, in the SAME ORDER.
const data = JSON.stringify({
  "documents": [
    {
      "description": "Service agreement",
      "optional": 0,
      "preview": 0,
      "checksumDocument": "9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08",
      "annotationParameters": [
        {
          "annotationText": "Signed by Evrotrust",
          "fontName": "Helvetica",
          "fontSize": 10,
          "fontColor": "#000000",
          "axisX": 100,
          "axisY": 150,
          "page": 1
        }
      ]
    },
    {
      "description": "Annex A - pricing",
      "optional": 1,
      "preview": 0,
      "checksumDocument": "60303ae22b998861bce3b28f33eec1be758a213c86c93c076dbe9f558c11c752",
      "annotationParameters": [
        {
          "annotationText": "Signed by Evrotrust",
          "fontName": "Helvetica",
          "fontSize": 10,
          "fontColor": "#000000",
          "axisX": 100,
          "axisY": 150,
          "page": 1
        }
      ]
    }
  ],
  "signInfo": {
    "type": "PDF2",
    "algorithm": "SHA256"
  },
  "groupDescription": "Service agreement and annex",
  "certificateType": 1,
  "coverage": 20000,
  "dateExpire": 1798761599,
  "BIOrequired": 0,
  "urlCallback": "https://your-server.example.com/evrotrust/callback",
  "vendorNumber": "YOUR_VENDOR_NUMBER",
  "users": [
    "users": [
    {
      "identificationNumber": "1234567890",
      "country": "BG",
      //"email": "user@example.com",
      //"phone": "+359123456789",
			//"automatedSignCertID": "string",
			//"automatedSignSealID": "string",
      "employee": 0,
      },
  ],
  "publicKey": "BASE64_ENCODED_PUBLIC_KEY"
});

const key = crypto.createHash('sha256').update(VENDOR_API_KEY).digest();
const authorization = crypto.createHmac('sha256', key).update(data).digest('hex');

const files = ['/path/to/agreement.pdf', '/path/to/annex-a.pdf'];

const form = new FormData();
form.append('data', data);
for (const file of files) {
  form.append(
    'document',
    new Blob([fs.readFileSync(file)], { type: 'application/pdf' }),
    file.split('/').pop()
  );
}

const response = await fetch(URL, {
  method: 'POST',
  headers: { Authorization: authorization },
  body: form,
});

console.log(response.status, await response.text());

