import hashlib, hmac, requests

VENDOR_API_KEY = 'xxx'
URL = 'https://api.sandbox.evrotrust.com/vendor/document/hash/online'

body = """{
  "document": {
    "hash": "9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08",
    "description": "Contract for signature",
    "dateExpire": 12345678
  },
  "signInfo": {
    "algorithm": "SHA-256"
  },
  "user": {
    "identificationNumber": "1234567890",
    "country": "BG",
    //"email": "user@example.com",
    //"phone": "+359123456789",
    //"automatedSignCertID": "<automatedSignCertID>",
    //"automatedSignSealID": "<automatedSignSealID>"
  },
  "certificateSerialNumber": "1A2B3C4D5E6F",
  "BIOrequired": 0,
  "vendorNumber": "YOUR_VENDOR_NUMBER",
  "urlCallback": "https://your-server.example.com/callback",
  "publicKey": "<publicKey>"
}"""

# Authorization: HMAC-SHA256 over the exact body bytes,
# keyed by the raw SHA-256 digest of the API key
key = hashlib.sha256(VENDOR_API_KEY.encode()).digest()
authorization = hmac.new(key, body.encode('utf-8'), hashlib.sha256).hexdigest()

response = requests.post(
    URL,
    headers={'Content-Type': 'application/json',
             'Authorization': authorization},
    data=body.encode('utf-8'),
    timeout=30,
)

print(response.status_code, response.text)

